const extraction = $input.item.json;

// Reference dates — try direct fields first (call workflow)
const deliverByDate = extraction.deliver_by_date || null;
const shipByDate = extraction.ship_by_date || null;

// Parse dates safely
function parseDate(val) {
  if (!val || val === '') return null;
  const d = new Date(val);
  return isNaN(d.getTime()) ? null : d;
}

const deliverBy = parseDate(deliverByDate);
const shipBy = parseDate(shipByDate);
const deliveryProvided = parseDate(extraction.delivery_date_provided);
const shipProvided = parseDate(extraction.ship_date_provided);

// Delay reason helper
const delayReason = extraction.delay_reason || 'Delay reason not provided';

let classification = null;
let classification_detail = null;
let extracted_date = null;
let extracted_date_type = null;
let needs_human_review = false;

// ── Scenario 1: No email/call found ─────────────────────────────────────────
if (!extraction.email_found) {
  classification = 'No reply yet';
  classification_detail = 'No supplier response received';
  extracted_date = null;
  extracted_date_type = null;
}

// ── Scenarios 13 & 14: Partial shipment — always human review ───────────────
else if (extraction.is_partial_shipment) {
  needs_human_review = true;
  const conservativeDate = (deliveryProvided && shipProvided)
    ? (deliveryProvided > shipProvided ? deliveryProvided : shipProvided)
    : (deliveryProvided || shipProvided);

  if (conservativeDate && deliverBy && conservativeDate <= deliverBy) {
    classification = 'On time';
    classification_detail = 'Partial shipment confirmed — flagged for human review to verify remaining quantity';
    extracted_date = extraction.delivery_date_provided || extraction.ship_date_provided;
    extracted_date_type = extraction.delivery_date_provided ? 'delivery_date' : 'ship_date';
  } else {
    classification = 'Delayed';
    classification_detail = `Partial shipment confirmed — flagged for human review to verify remaining quantity and delay — ${delayReason}`;
    extracted_date = extraction.delivery_date_provided || extraction.ship_date_provided;
    extracted_date_type = extraction.delivery_date_provided ? 'delivery_date' : 'ship_date';
  }
}

// ── Scenarios 7 & 8: Both delivery date and ship date provided ──────────────
else if (deliveryProvided && shipProvided) {
  const deliveryOnTime = deliverBy ? deliveryProvided <= deliverBy : true;
  const shipOnTime = shipBy ? shipProvided <= shipBy : true;

  if (deliveryOnTime && shipOnTime) {
    classification = 'On time';
    classification_detail = `Shipped ${extraction.ship_date_provided} and delivery confirmed by ${extraction.delivery_date_provided}, both within agreed dates`;
    extracted_date = extraction.delivery_date_provided;
    extracted_date_type = 'delivery_date';
  } else {
    const useDelivery = !deliveryOnTime;
    classification = 'Delayed';
    extracted_date = useDelivery ? extraction.delivery_date_provided : extraction.ship_date_provided;
    extracted_date_type = useDelivery ? 'delivery_date' : 'ship_date';
    const referenceDate = useDelivery ? deliverByDate : shipByDate;
    classification_detail = `Conservative date used — ${extracted_date_type === 'delivery_date' ? 'delivery' : 'shipped'} ${extracted_date} after ${extracted_date_type === 'delivery_date' ? 'deliver-by' : 'ship-by'} date of ${referenceDate} — ${delayReason}`;
  }
}

// ── Scenarios 3 & 4: Delivery date only ─────────────────────────────────────
else if (deliveryProvided) {
  if (deliverBy && deliveryProvided <= deliverBy) {
    classification = 'On time';
    classification_detail = `Delivery confirmed by ${extraction.delivery_date_provided}, on or before agreed date of ${deliverByDate}`;
    extracted_date = extraction.delivery_date_provided;
    extracted_date_type = 'delivery_date';
  } else if (deliverBy && deliveryProvided > deliverBy) {
    classification = 'Delayed';
    classification_detail = `New delivery date ${extraction.delivery_date_provided}, after agreed deliver-by date of ${deliverByDate} — ${delayReason}`;
    extracted_date = extraction.delivery_date_provided;
    extracted_date_type = 'delivery_date';
  } else {
    classification = 'On time TBC';
    classification_detail = `Delivery date ${extraction.delivery_date_provided} provided but no deliver-by reference date available for comparison`;
    extracted_date = extraction.delivery_date_provided;
    extracted_date_type = 'delivery_date';
  }
}

// ── Scenarios 5 & 6: Ship date only ─────────────────────────────────────────
else if (shipProvided) {
  if (shipBy && shipProvided <= shipBy) {
    classification = 'On time';
    classification_detail = `Shipped ${extraction.ship_date_provided}, on or before ship-by date of ${shipByDate}`;
    extracted_date = extraction.ship_date_provided;
    extracted_date_type = 'ship_date';
  } else if (shipBy && shipProvided > shipBy) {
    classification = 'Delayed';
    classification_detail = `Shipped ${extraction.ship_date_provided}, after ship-by date of ${shipByDate} — ${delayReason}`;
    extracted_date = extraction.ship_date_provided;
    extracted_date_type = 'ship_date';
  } else {
    classification = 'On time TBC';
    classification_detail = `Ship date ${extraction.ship_date_provided} provided but no ship-by reference date available for comparison`;
    extracted_date = extraction.ship_date_provided;
    extracted_date_type = 'ship_date';
  }
}

// ── Scenario 9: Supplier said on time, no dates ──────────────────────────────
else if (extraction.supplier_stated_on_time === true) {
  classification = 'On time TBC';
  classification_detail = 'Supplier confirmed on time but no specific date provided';
  extracted_date = null;
  extracted_date_type = null;
}

// ── Scenarios 10 & 11: Supplier said delayed ─────────────────────────────────
else if (extraction.supplier_stated_delayed === true) {
  classification = 'Delayed TBC';
  classification_detail = extraction.approximate_date_expression
    ? `Delay acknowledged, supplier indicated ${extraction.approximate_date_expression} but no specific date confirmed — ${delayReason}`
    : `Delay acknowledged, no revised date provided — ${delayReason}`;
  extracted_date = null;
  extracted_date_type = null;
}

// ── Scenario 12: Tracking info but no dates ──────────────────────────────────
else if (extraction.tracking_number || extraction.carrier) {
  classification = 'Shipped TBC';
  const trackingInfo = [
    extraction.carrier ? `via ${extraction.carrier}` : null,
    extraction.tracking_number ? `tracking ${extraction.tracking_number}` : null
  ].filter(Boolean).join(', ');
  classification_detail = `Dispatched ${trackingInfo}, no ship or delivery date specified`;
  extracted_date = null;
  extracted_date_type = null;
}

// ── Scenario 2: Found but nothing determinable ───────────────────────────────
else {
  classification = 'Unclear';
  classification_detail = extraction.raw_supplier_statement;
  extracted_date = null;
  extracted_date_type = null;
}

// ── Scenario 15: Contradiction check ─────────────────────────────────────────
if (classification === 'Delayed' && extraction.supplier_stated_on_time === true) {
  needs_human_review = true;
  classification_detail = classification_detail + ' — WARNING: supplier stated on time but date indicates delay';
}
if (classification === 'On time' && extraction.supplier_stated_delayed === true) {
  needs_human_review = true;
  classification_detail = classification_detail + ' — WARNING: supplier stated delayed but date is within agreed window';
}

if (extraction.confidence === 'Low') {
  needs_human_review = true;
}

return {
  json: {
    ...extraction,
    deliver_by_date: deliverByDate,
    ship_by_date: shipByDate,
    classification,
    classification_detail,
    extracted_date,
    extracted_date_type,
    needs_human_review
  }
};
